def backfill_step3_requests(apps, schema_editor):
    """
    Safely backfill existing BloodRequest rows (additive, reversible):
    - Determine request_mode ('PROXY' if attendant_name is set and differs from patient_name, else 'SELF')
    - Compute units_received from DONATED/CONFIRMED matches/acceptances (capped at units_needed)
    - Compute units_pending from active ACCEPTED/ON_THE_WAY/ARRIVED matches/acceptances
      while maintaining invariant: units_received + units_pending <= units_needed.
    """
    BloodRequest = apps.get_model('api', 'BloodRequest')
    DonationMatch = apps.get_model('api', 'DonationMatch')
    RequestAcceptance = apps.get_model('api', 'RequestAcceptance')

    for req in BloodRequest.objects.all().iterator():
        needed = max(1, req.units_needed or 1)
        attendant = (req.attendant_name or '').strip()
        patient = (req.patient_name or '').strip()
        mode = 'PROXY' if (attendant and attendant.lower() != patient.lower()) else 'SELF'

        donated_matches = DonationMatch.objects.filter(
            request_id=req.id,
            status='DONATED',
        ).count()
        donated_acceptances = RequestAcceptance.objects.filter(
            request_id=req.id,
            status__in=['DONATED', 'CONFIRMED'],
        ).count()
        received = min(needed, max(donated_matches, donated_acceptances))
        if req.status in ('CLOSED', 'FULFILLED', 'DONATED') and received == 0:
            received = needed

        active_matches = DonationMatch.objects.filter(
            request_id=req.id,
            role='PRIMARY',
            status__in=['ACCEPTED', 'ON_THE_WAY', 'ARRIVED'],
        ).count()
        active_acceptances = RequestAcceptance.objects.filter(
            request_id=req.id,
            is_standby=False,
            status__in=['ACCEPTED', 'ON_THE_WAY', 'ARRIVED'],
        ).count()
        pending_raw = max(active_matches, active_acceptances)
        pending = max(0, min(needed - received, pending_raw))

        BloodRequest.objects.filter(pk=req.pk).update(
            units_needed=needed,
            units_received=received,
            units_pending=pending,
            request_mode=mode,
        )


